old = new = None
for line in open('/tmp/gdiff.txt'):
    if line.startswith('-') and not line.startswith('---'):
        old = line[1:]
    elif line.startswith('+') and not line.startswith('+++'):
        new = line[1:]
# find the first difference position
i = 0
while i < min(len(old), len(new)) and old[i] == new[i]:
    i += 1
print('first diff at char', i)
print('OLD ...', repr(old[max(0,i-60):i+140]))
print('NEW ...', repr(new[max(0,i-60):i+140]))
""}

